import { test } from "node:test";
import assert from "node:assert/strict";
import { describeFailure } from "../../src/schedule.mjs";
import { DurationError, parseDuration } from "../../src/parse-duration.mjs";

test("describeFailure formats a DurationError via JSON.stringify of its input (string input)", () => {
	let caught;
	try {
		parseDuration("not-a-duration");
	} catch (err) {
		caught = err;
	}
	assert.ok(caught instanceof DurationError);
	assert.equal(describeFailure(caught), `bad duration ${JSON.stringify(caught.input)}`);
	assert.equal(describeFailure(caught), `bad duration "not-a-duration"`);
});

test("describeFailure formats a DurationError via JSON.stringify of its input (non-string input)", () => {
	let caught;
	try {
		parseDuration(5000);
	} catch (err) {
		caught = err;
	}
	assert.ok(caught instanceof DurationError);
	assert.equal(describeFailure(caught), `bad duration ${JSON.stringify(caught.input)}`);
	assert.equal(describeFailure(caught), "bad duration 5000");
});

test("describeFailure formats a directly constructed DurationError the same way, including a null input", () => {
	const err = new DurationError("a duration must be a string", null);
	assert.equal(describeFailure(err), `bad duration ${JSON.stringify(err.input)}`);
	assert.equal(describeFailure(err), "bad duration null");
});

test("describeFailure treats a plain Error as unexpected, not a duration error", () => {
	const err = new Error("boom");
	assert.equal(describeFailure(err), `unexpected: ${err.message}`);
	assert.equal(describeFailure(err), "unexpected: boom");
});

test("describeFailure treats other built-in error types as unexpected too", () => {
	const typeErr = new TypeError("wrong type");
	assert.equal(describeFailure(typeErr), "unexpected: wrong type");

	const rangeErr = new RangeError("out of range");
	assert.equal(describeFailure(rangeErr), "unexpected: out of range");
});

