import { test } from "node:test";
import assert from "node:assert/strict";
import { nextRun } from "../../src/schedule.mjs";

test("nextRun returns exactly startMs when now is well before the start instant", () => {
	assert.strictEqual(nextRun(1000, "10ms", 0), 1000);
});

test("nextRun returns exactly startMs when now is just one instant before the start", () => {
	assert.strictEqual(nextRun(1000, "10ms", 999), 1000);
});

test("nextRun does NOT early-return startMs when now equals the start instant; it computes one full period ahead", () => {
	assert.strictEqual(nextRun(1000, "10ms", 1000), 1010);
});

test("nextRun behaves the same one instant after start as it does exactly at start", () => {
	assert.strictEqual(nextRun(1000, "10ms", 1001), 1010);
});

test("the start-instant boundary holds with a different startMs/interval pair too", () => {
	assert.strictEqual(nextRun(500000, "1s", 499999), 500000);
	assert.strictEqual(nextRun(500000, "1s", 500000), 501000);
	assert.strictEqual(nextRun(500000, "1s", 500001), 501000);
});

