import { test } from "node:test";
import assert from "node:assert/strict";
import { DurationError, parseDuration } from "../../src/parse-duration.mjs";

/**
 * parseDuration's contract is that ANY non-string input raises this module's own DurationError, carrying the
 * exact offending value on `.input` — never a stray error raised by accident deeper down (for example a TypeError
 * from calling a string method on a value that has none).
 */
function assertRejectsWithDurationError(value) {
	let caught;
	try {
		parseDuration(value);
	} catch (err) {
		caught = err;
	}
	assert.ok(
		caught instanceof DurationError,
		`expected a DurationError for ${JSON.stringify(value)}, but caught ${caught && caught.constructor && caught.constructor.name}: ${caught && caught.message}`,
	);
	assert.equal(caught.name, "DurationError");
	assert.strictEqual(caught.input, value);
}

test("parseDuration rejects a number with its own DurationError carrying the exact value", () => {
	assertRejectsWithDurationError(5000);
});

test("parseDuration rejects null with its own DurationError carrying the exact value", () => {
	assertRejectsWithDurationError(null);
});

test("parseDuration rejects undefined with its own DurationError carrying the exact value", () => {
	assertRejectsWithDurationError(undefined);
});

test("parseDuration rejects a plain object with its own DurationError carrying the exact value", () => {
	const value = { ms: 10 };
	assertRejectsWithDurationError(value);
});

test("parseDuration rejects an array with its own DurationError carrying the exact value", () => {
	const value = ["10ms"];
	assertRejectsWithDurationError(value);
});

test("parseDuration rejects a boolean with its own DurationError carrying the exact value", () => {
	assertRejectsWithDurationError(true);
});

